 return{title:name,type:"Specific",duration:"30–60 min",effort:"Controlled",why:"Complete the current phase-specific session with clean technique and adaptive restraint.",steps:[ex("Main session","Follow current block target","—","Stop for focal pain, altered gait or red recovery flags.","Specific")]};
