function renderToday(){const d=todayCheckin(),det=makeSession(sessionName()),done=todayWorkout();$("todayDate").textContent=new Date().toLocaleDateString(undefined,{weekday:"short",month:"short",day:"numeric"});$("todayWorkoutName").textContent=det.title;$("todayWorkoutType").textContent=det.type.toUpperCase();$("todayWorkoutMeta").textContent=det.duration+" · "+det.effort;$("taskWorkoutSub").textContent=done?"Completed today":"Follow the adaptive prescription";const score=d?.score||0;$("readinessScore").textContent=d?score:"—";$("scoreRing").style.setProperty("--score",score);$("scoreRing").style.setProperty("--ring",d?(d.overall==="GREEN"?"var(--green)":d.overall==="YELLOW"?"var(--yellow)":"var(--red)"):"var(--green)");$("readinessLabel").textContent=d?(d.overall==="GREEN"?"Good":d.overall==="YELLOW"?"Caution":"Recover"):"Check in";$("readinessLabel").style.color=d?(d.overall==="GREEN"?"var(--green)":d.overall==="YELLOW"?"var(--yellow)":"var(--red)"):"";$("readinessMessage").textContent=d?(d.overall==="GREEN"?"You’re ready for the planned session.":d.overall==="YELLOW"?"Train, but reduce today’s stress.":"Recovery takes priority today."):"Log your morning metrics to personalize today’s training.";$("todayHRV").textContent=d?.hrv??"—";$("todayRHR").textContent=d?.rhr??"—";$("todaySleep").textContent=d?.sleep??"—";const state={taskCheckin:!!d,taskWorkout:!!done,taskNutrition:taskDone("nutrition"),taskMobility:taskDone("mobility")};Object.entries(state).forEach(x=>{const el=$(x[0]);el.classList.toggle("done",x[1]);el.querySelector(".task-circle").textContent=x[1]?"✓":"○"});$("todayTaskCount").textContent=Object.values(state).filter(Boolean).length+"/4"}
function renderTrain(){const det=makeSession(sessionName()),c=todayCheckin(),label=!c?"CHECK IN":c.overall==="GREEN"?"PRIMARY":c.overall==="YELLOW"?"MODIFIED":"RECOVERY";$("workoutKicker").textContent="TODAY · WEEK "+currentWeek()+" · "+blockForWeek(currentWeek()).name.toUpperCase();$("workoutTitle").textContent=det.title;$("workoutWhy").textContent=det.why;$("workoutTags").innerHTML='<span>◷ '+det.duration+'</span><span>◈ '+det.effort+'</span><span>'+det.type+'</span>';$("sessionStatus").textContent=label;$("sessionStatus").className="session-status "+(!c?"yellow":c.overall==="YELLOW"?"yellow":c.overall==="RED"?"red":"");$("exerciseCount").textContent=det.steps.length+" movements";$("workoutPrescription").innerHTML=det.steps.map((e,i)=>'<button class="exercise-card" data-i="'+i+'"><div class="exercise-thumb">'+svg(e.name)+'</div><div class="exercise-copy"><strong>'+(i+1)+'. '+e.name+'</strong><span>'+e.dose+'</span><small>Rest: '+e.rest+'</small></div><b>›</b></button>').join("");$("workoutPrescription").querySelectorAll(".exercise-card").forEach(b=>b.onclick=()=>openExercise(det.steps[+b.dataset.i]));renderLibrary()}
function libraryExercises(){const map=new Map();[...A,...B,ex("RKC plank","3 × 20–40 sec","60 sec","Squeeze glutes, quads and abs hard.","Core"),ex("Push-ups","4–6 submaximal sets","2 min","Strict reps; stop before failure.","Bodyweight"),ex("Easy row","30–60 min","Continuous","Conversational effort.","Row")].forEach(e=>map.set(e.name,e));return[...map.values()].sort((a,b)=>a.name.localeCompare(b.name))}
function renderLibrary(q=""){const all=libraryExercises(),query=q.trim().toLowerCase(),arr=query?all.filter(e=>(e.name+" "+e.type+" "+e.cue).toLowerCase().includes(query)):all;if($("libraryCount"))$("libraryCount").textContent=arr.length+" exercise"+(arr.length===1?"":"s");$("exerciseLibrary").innerHTML=arr.length?arr.map((e,i)=>'<button class="library-item" data-i="'+i+'"><div class="library-thumb">'+svg(e.name)+'</div><div><strong>'+e.name+'</strong><small>'+e.type+' · '+e.dose+'</small></div><b>›</b></button>').join(""):'<div class="empty-search">No matching exercises.</div>';$("exerciseLibrary").querySelectorAll(".library-item").forEach(b=>b.onclick=()=>openExercise(arr[+b.dataset.i]))}
function dateFor(w,i){const d=new Date(programStart());d.setHours(12,0,0,0);d.setDate(d.getDate()+(w-1)*7+i);return d}
let viewedMonth=new Date();
const phasePalette={"Rebuild":"#48a7ff","Build":"#7d8cff","Specificity":"#ad73e6","Work Capacity":"#ef9a57","Taper":"#55cfa0"};
function isHighVolumeSession(name){return /long|quality|threshold|specific|medium aerobic/i.test(name)}
function nutritionForWeek(w,name){const high=isHighVolumeSession(name);if(w<=20)return{phase:"Aggressive Recomposition",cal:high?1650:1450,protein:185,carbs:high?140:90,fat:40,why:high?"Higher carbohydrate allowance for a longer or harder session.":"Low-volume Phase A target from the submitted nutrition architecture."};if(w<=22)return{phase:"Metabolic Pivot · Step 1",cal:1950,protein:185,carbs:190,fat:50,why:"Step calories upward before high-volume work expands."};if(w<=24)return{phase:"Metabolic Pivot · Step 2",cal:2250,protein:185,carbs:240,fat:60,why:"Second step before full performance fueling."};return{phase:"Performance Fueling",cal:high?4000:3400,protein:200,carbs:high?600:450,fat:88,why:high?"High-demand target emphasizing glycogen replacement.":"Baseline Phase B performance target."}}
function nutritionHtml(w,name){const n=nutritionForWeek(w,name);return '<div class="nutrition-hero"><small>'+n.phase.toUpperCase()+'</small><strong>≈ '+n.cal.toLocaleString()+' kcal</strong><p>'+n.why+'</p></div><div class="macro-grid"><div><span>Protein</span><strong>'+n.protein+' g</strong></div><div><span>Carbs</span><strong>'+n.carbs+' g</strong></div><div><span>Fat</span><strong>'+n.fat+' g</strong></div></div><div class="nutrition-note"><strong>Adaptive rule</strong><p>Readiness and body-weight trend override an aggressive deficit when recovery or performance deteriorates.</p></div>'}
function programWeekForDate(d){const a=new Date(programStart()),b=new Date(d);a.setHours(12,0,0,0);b.setHours(12,0,0,0);return Math.max(1,Math.min(56,Math.floor((b-a)/604800000)+1))}
function programDayIndex(d){const a=new Date(programStart()),b=new Date(d);a.setHours(12,0,0,0);b.setHours(12,0,0,0);const days=Math.floor((b-a)/86400000);return((days%7)+7)%7}
function dateSession(d){const w=programWeekForDate(d),bl=blockForWeek(w),name=daysFor(bl)[programDayIndex(d)];return{w,bl,name,det:makeSession(name)}}
function dateState(d){const k=dayKey(d),check=logs().some(x=>dayKey(x.date)===k),work=workouts().some(x=>dayKey(x.date)===k&&x.completed==="YES"),failed=JSON.parse(localStorage.failedDays||"[]").includes(k);return{check,work,failed}}
function openDaySheet(d,tab="training"){const x=dateSession(d);window.selectedDay=new Date(d);$("daySheetKicker").textContent="WEEK "+x.w+" · "+x.bl.name.toUpperCase();$("daySheetTitle").textContent=d.toLocaleDateString(undefined,{weekday:"long",month:"long",day:"numeric"});$("daySheet").classList.remove("hidden");document.querySelectorAll(".day-tab").forEach(b=>b.classList.toggle("active",b.dataset.daytab===tab));renderDaySheetTab(tab)}
function renderDaySheetTab(tab){const d=window.selectedDay||new Date(),x=dateSession(d),state=dateState(d);if(tab==="nutrition"){$("daySheetBody").innerHTML=nutritionHtml(x.w,x.name);return}$("daySheetBody").innerHTML='<div class="day-status-line"><span class="'+(state.check?"done":"")+'">'+(state.check?"✓":"○")+' Check-in</span><span class="'+(state.work?"done":"")+'">'+(state.work?"✓":"○")+' Training</span>'+(state.failed?'<span class="failed">× Missed</span>':'')+'</div><div class="day-training-hero"><small>'+x.det.type.toUpperCase()+'</small><h3>'+x.det.title+'</h3><p>'+x.det.why+'</p></div><div class="day-exercises">'+x.det.steps.map((e,i)=>'<button data-dayex="'+i+'"><b>'+(i+1)+'</b><div><strong>'+e.name+'</strong><small>'+e.dose+' · '+e.rest+'</small></div><span>›</span></button>').join("")+'</div>';$("daySheetBody").querySelectorAll("[data-dayex]").forEach(b=>b.onclick=()=>openExercise(x.det.steps[+b.dataset.dayex]))}
function renderMonth(){const base=new Date(viewedMonth.getFullYear(),viewedMonth.getMonth(),1,12),year=base.getFullYear(),month=base.getMonth();$("monthTitle").textContent=base.toLocaleDateString(undefined,{month:"long",year:"numeric"});const first=(base.getDay()+6)%7,last=new Date(year,month+1,0).getDate(),cells=[];for(let i=0;i<first;i++)cells.push('<div class="month-cell empty"></div>');for(let day=1;day<=last;day++){const d=new Date(year,month,day,12),afterStart=!localStorage.programStart||d>=new Date(programStart()),w=programWeekForDate(d),macro=macroForWeek(w),state=dateState(d),today=d.toDateString()===new Date().toDateString(),future=d>new Date();cells.push('<button class="month-cell '+(today?"today ":"")+(state.check&&state.work?"complete ":"")+(state.failed?"failed ":"")+(future?"future ":"")+'" data-date="'+d.toISOString()+'" '+(!afterStart?"disabled":"")+'><span>'+day+'</span><i style="background:'+phasePalette[macro.name]+'"></i></button>')} $("monthGrid").innerHTML=cells.join("");$("monthLegend").innerHTML=macroPhases.map(x=>'<span><i style="background:'+phasePalette[x[0]]+'"></i>'+x[0]+'</span>').join("");$("monthGrid").querySelectorAll("[data-date]").forEach(b=>b.onclick=()=>openDaySheet(new Date(b.dataset.date)))}
function renderWeek(){const w=viewedWeek,bl=blockForWeek(w),days=daysFor(bl),st=dateFor(w,0),en=dateFor(w,6);$("weekTitle").textContent="Week "+w;$("weekRange").textContent=st.toLocaleDateString(undefined,{month:"short",day:"numeric"})+" – "+en.toLocaleDateString(undefined,{month:"short",day:"numeric"});$("weekSummary").innerHTML='<div class="week-card"><div class="week-overview"><small>'+bl.name.toUpperCase()+'</small><strong>'+bl.focus+'</strong><p>'+bl.run+' · '+bl.ruck+'</p></div>'+days.map((name,i)=>{const det=makeSession(name),date=dateFor(w,i),is=date.toDateString()===todayKey(),state=dateState(date);return'<div class="day-row '+(state.check&&state.work?"done ":"")+(state.failed?"failed ":"")+(is?"today-row":"")+'"><button class="day-button" data-i="'+i+'"><div class="day-date"><strong>'+date.toLocaleDateString(undefined,{weekday:"short"})+'</strong><small>'+date.getDate()+'</small></div><span class="day-state">'+(state.failed?"×":state.check&&state.work?"✓":"○")+'</span><div class="day-desc"><strong>'+det.title+'</strong><small>'+det.type+' · '+det.effort+'</small></div><span class="day-chevron">›</span></button></div>'}).join("")+'</div>';$("weekSummary").querySelectorAll(".day-button").forEach(btn=>btn.onclick=()=>openDaySheet(dateFor(w,+btn.dataset.i)))}
function phaseComplete(bl){const hs=workouts().filter(x=>x.week>=bl.start&&x.week<=bl.end&&x.completed==="YES"),total=(bl.end-bl.start+1)*7,done=new Set(hs.map(x=>new Date(x.date).toDateString())).size;return{done,total,pct:Math.min(100,Math.round(done/total*100))}}
const macroPhases=[["Rebuild",1,12,"Recondition, build aerobic base and restore tissue tolerance."],["Build",13,24,"Increase running, weighted-pack walking and controlled faster work."],["Specificity",25,40,"Shift toward running, loaded movement, bodyweight strength and consecutive-day durability."],["Work Capacity",41,52,"Build high accumulated workload and prolonged time on feet."],["Taper",53,56,"Dissipate fatigue while retaining selected intensity."]];
const phaseObjectives=[
 {name:"Establish the system",goal:s=>s.checkins>=7,progress:s=>Math.min(1,s.checkins/7),label:s=>s.checkins+"/7 check-ins"},
 {name:"Build strength consistency",goal:s=>s.strength>=4,progress:s=>Math.min(1,s.strength/4),label:s=>s.strength+"/4 strength sessions"},
 {name:"Build the engine",goal:s=>s.aerobic>=4,progress:s=>Math.min(1,s.aerobic/4),label:s=>s.aerobic+"/4 aerobic sessions"},
 {name:"Stack two complete weeks",goal:s=>s.completeDays>=14,progress:s=>Math.min(1,s.completeDays/14),label:s=>s.completeDays+"/14 complete days"},
 {name:"Twenty-one day discipline",goal:s=>s.checkins>=21,progress:s=>Math.min(1,s.checkins/21),label:s=>s.checkins+"/21 check-ins"},
 {name:"Strength base II",goal:s=>s.strength>=8,progress:s=>Math.min(1,s.strength/8),label:s=>s.strength+"/8 strength sessions"},
 {name:"Aerobic base II",goal:s=>s.aerobic>=8,progress:s=>Math.min(1,s.aerobic/8),label:s=>s.aerobic+"/8 aerobic sessions"},
 {name:"Four complete weeks",goal:s=>s.completeDays>=28,progress:s=>Math.min(1,s.completeDays/28),label:s=>s.completeDays+"/28 complete days"},
 {name:"Forty check-ins",goal:s=>s.checkins>=40,progress:s=>Math.min(1,s.checkins/40),label:s=>s.checkins+"/40 check-ins"},
 {name:"Twelve strength sessions",goal:s=>s.strength>=12,progress:s=>Math.min(1,s.strength/12),label:s=>s.strength+"/12 strength sessions"},
 {name:"Twelve engine sessions",goal:s=>s.aerobic>=12,progress:s=>Math.min(1,s.aerobic/12),label:s=>s.aerobic+"/12 aerobic sessions"},
 {name:"Phase finisher",goal:s=>s.mastery>=.9,progress:s=>Math.min(1,s.mastery/.9),label:s=>Math.round(s.mastery*100)+"% mastery"}
];
function macroForWeek(w){const x=macroPhases.find(p=>w>=p[1]&&w<=p[2])||macroPhases[0];return{name:x[0],start:x[1],end:x[2],focus:x[3]}}
function macroStats(p){const ls=logs().filter(x=>x.week>=p.start&&x.week<=p.end),ws=workouts().filter(x=>x.week>=p.start&&x.week<=p.end&&x.completed==="YES"),failed=JSON.parse(localStorage.failedDays||"[]").filter(k=>{const w=programWeekForDate(new Date(k));return w>=p.start&&w<=p.end}).length,checkKeys=new Set(ls.map(x=>dayKey(x.date))),completeKeys=new Set(ws.filter(w=>checkKeys.has(dayKey(w.date))).map(x=>dayKey(x.date))),total=(p.end-p.start+1)*7;return{checkins:checkKeys.size,strength:ws.filter(x=>/strength|carry/i.test(x.session||"")).length,aerobic:ws.filter(x=>/run|row|aerobic|recovery/i.test(x.session||"")).length,completeDays:completeKeys.size,failed,total,mastery:Math.max(0,(completeKeys.size-failed*.5)/total)}}
function renderProgram(){const cur=macroForWeek(currentWeek()),stats=macroStats(cur),completed=phaseObjectives.filter(o=>o.goal(stats)).length,tier=Math.min(Math.floor(completed/4),2),shown=phaseObjectives.slice(tier*4,tier*4+4),pc=Math.round(stats.mastery*100);$("currentPhaseCard").innerHTML='<div class="phase-feature-top"><div><small>PHASE '+(macroPhases.findIndex(x=>x[0]===cur.name)+1)+' OF '+macroPhases.length+'</small><h2>'+cur.name+'</h2><p>Weeks '+cur.start+'–'+cur.end+'<br>'+cur.focus+'</p></div><div class="xp-chip">LEVEL '+(tier+1)+'</div></div><div class="phase-progress-box"><div class="phase-ring" style="--p:'+pc+'"><span>'+pc+'%</span></div><div class="phase-progress-copy"><strong>'+stats.completeDays+' complete days</strong><small>'+stats.failed+' failed · '+missedDays().length+' unresolved</small><div class="progress-bar"><i style="width:'+pc+'%"></i></div></div></div>';$("objectiveMeta").innerHTML='<strong>Objective Set '+(tier+1)+'</strong><span>Complete all four to unlock the next set.</span>';$("milestoneCount").textContent=completed+"/"+phaseObjectives.length;$("phaseMilestones").innerHTML=shown.map((o,i)=>{const done=o.goal(stats),pct=Math.round(o.progress(stats)*100);return'<div class="milestone quest '+(done?"done":"")+'"><span class="milestone-state">'+(done?"✓":tier*4+i+1)+'</span><div><strong>'+o.name+'</strong><small>'+o.label(stats)+'</small><div class="quest-progress"><i style="width:'+pct+'%"></i></div></div><b>'+(done?"+100 XP":pct+"%")+'</b></div>'}).join("");$("programBlocks").innerHTML=macroPhases.map((x,i)=>{const p={name:x[0],start:x[1],end:x[2],focus:x[3]},st=macroStats(p),pct=Math.round(st.mastery*100),active=cur.name===p.name;return'<div class="phase-card '+(active?"current":"")+'"><span class="phase-num">'+(i+1)+'</span><div><strong>'+p.name+'</strong><small>Weeks '+p.start+'–'+p.end+'</small></div><span class="phase-pct">'+pct+'%</span></div>'}).join("")}
function draw(id,a){const c=$(id),ctx=c.getContext("2d"),w=c.clientWidth||320,h=160,d=devicePixelRatio||1;c.width=w*d;c.height=h*d;ctx.scale(d,d);ctx.clearRect(0,0,w,h);if(a.length<2){ctx.fillStyle="#8fa8bd";ctx.font="12px -apple-system, BlinkMacSystemFont, sans-serif";ctx.fillText("Save more check-ins to build this trend.",10,80);return}const mn=Math.min(...a),mx=Math.max(...a),sp=mx-mn||1,p=12;ctx.strokeStyle="#1794ff";ctx.lineWidth=2.5;ctx.beginPath();a.forEach((v,i)=>{const x=p+i*(w-2*p)/(a.length-1),y=h-p-(v-mn)*(h-2*p)/sp;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}
function renderTrends(){const l=logs().slice(0,28).reverse(),map={RED:30,YELLOW:65,GREEN:90},wt=l.filter(x=>Number.isFinite(x.weight)).map(x=>x.weight);$("trendRecovery").textContent=l.length?l.length+" check-ins":"No data";$("trendWeight").textContent=wt.length?wt.at(-1).toFixed(1)+" lb":"No data";requestAnimationFrame(()=>{draw("recoveryChart",l.map(x=>x.score||map[x.overall]||50));draw("weightChart",wt)});const a=[...logs().map(x=>({...x,k:"Check-in"})),...workouts().map(x=>({...x,k:"Session"}))].sort((x,y)=>new Date(y.date)-new Date(x.date)).slice(0,8);$("trendLogList").innerHTML=a.length?a.map(x=>'<div class="log-card"><div><strong>'+(x.k==="Session"?x.session:"Morning check-in")+'</strong><small>'+new Date(x.date).toLocaleDateString()+' · Week '+x.week+'</small></div><small>'+(x.k==="Session"?(x.completed||""):(x.overall||""))+'</small></div>').join(""):'<div class="log-card"><small>No activity saved yet.</small></div>';countRecords()}
function openCheckin(){$("checkinSheet").classList.remove("hidden");requiredFields();bindInfo($("checkinSheet"))}function closeCheckin(){$("checkinSheet").classList.add("hidden")}function closeModal(){$("infoModal").classList.add("hidden")}function bindInfo(root){(root||document).querySelectorAll(".info-dot[data-term]").forEach(b=>b.onclick=e=>{e.stopPropagation();openInfo(b.dataset.term)})}
function switchTab(t){$("headerAction").style.display=t==="today"?"grid":"none";document.querySelectorAll(".screen").forEach(x=>x.classList.remove("active"));$(t).classList.add("active");document.querySelectorAll(".tab").forEach(x=>x.classList.toggle("active",x.dataset.target===t));$("pageTitle").textContent=t==="workout"?"Train":t.charAt(0).toUpperCase()+t.slice(1);$("todayDate").textContent=t==="today"?new Date().toLocaleDateString(undefined,{weekday:"short",month:"short",day:"numeric"}):"";window.scrollTo({top:0,left:0,behavior:"instant"});if(t==="workout")renderTrain();if(t==="week")renderWeek();if(t==="trends")renderTrends();if(t==="program")renderProgram()}
function renderAll(){applyBaselines();renderMissedBanner();renderToday();renderTrain();renderWeek();renderTrends();renderProgram();requiredFields();bindInfo(document)}
document.querySelectorAll(".tab").forEach(b=>b.onclick=()=>switchTab(b.dataset.target));$("headerAction").onclick=()=>switchTab("week");$("taskCheckin").onclick=openCheckin;$("todayWorkoutCard").onclick=()=>switchTab("workout");$("taskWorkout").onclick=()=>switchTab("workout");$("taskNutrition").onclick=()=>openDaySheet(new Date(),"nutrition");$("taskMobility").onclick=()=>{setTask("mobility",!taskDone("mobility"));renderToday()};$("closeCheckin").onclick=closeCheckin;$("checkinSheet").onclick=e=>{if(e.target===$("checkinSheet"))closeCheckin()};$("evaluateBtn").onclick=evaluate;$("saveBtn").onclick=saveCheckin;$("completeWorkoutQuick").onclick=()=>saveWorkout("YES");$("completeWorkout").onclick=()=>saveWorkout(val("completed")||"YES");$("modalClose").onclick=closeModal;$("modalDone").onclick=closeModal;$("infoModal").onclick=e=>{if(e.target===$("infoModal"))closeModal()};document.querySelectorAll(".calendar-mode-btn").forEach(b=>b.onclick=()=>{document.querySelectorAll(".calendar-mode-btn").forEach(x=>x.classList.toggle("active",x===b));$("weekView").classList.toggle("hidden",b.dataset.calview!=="week");$("monthView").classList.toggle("hidden",b.dataset.calview!=="month");if(b.dataset.calview==="month")renderMonth()});$("prevMonth").onclick=()=>{viewedMonth=new Date(viewedMonth.getFullYear(),viewedMonth.getMonth()-1,1);renderMonth()};$("nextMonth").onclick=()=>{viewedMonth=new Date(viewedMonth.getFullYear(),viewedMonth.getMonth()+1,1);renderMonth()};$("daySheetClose").onclick=()=>$("daySheet").classList.add("hidden");$("daySheet").onclick=e=>{if(e.target===$("daySheet"))$("daySheet").classList.add("hidden")};document.querySelectorAll(".day-tab").forEach(b=>b.onclick=()=>{document.querySelectorAll(".day-tab").forEach(x=>x.classList.toggle("active",x===b));renderDaySheetTab(b.dataset.daytab)});$("prevWeek").onclick=()=>{viewedWeek=Math.max(1,viewedWeek-1);renderWeek()};$("nextWeek").onclick=()=>{viewedWeek=Math.min(56,viewedWeek+1);renderWeek()};if($("librarySearch"))$("librarySearch").addEventListener("input",e=>renderLibrary(e.target.value));document.querySelectorAll(".segment").forEach(b=>b.onclick=()=>{document.querySelectorAll(".segment").forEach(x=>x.classList.toggle("active",x===b));$("trainSessionView").classList.toggle("hidden",b.dataset.trainview!=="session");$("trainLibraryView").classList.toggle("hidden",b.dataset.trainview!=="library")});
